const drawBlip = (key, label, sub, color) => {
  if (!pos[key]) return; const [x,y] = pos[key];
  el("circle", {cx:x, cy:y, r:4, fill:color});
  el("circle", {cx:x, cy:y, r:8, fill:"none", stroke:color, opacity:.35});
  const t = el("text", {x:x+11, y:y+3, "class":"blip-label"}); t.textContent = label;
  const s = el("text", {x:x+11, y:y+15, "class":"blip-sub"}); s.textContent = sub;
};

input.new_string:
const drawBlip = (key, label, sub, color, alignEnd) => {
  if (!pos[key]) return; const [x,y] = pos[key];
  el("circle", {cx:x, cy:y, r:4, fill:color});
  el("circle", {cx:x, cy:y, r:8, fill:"none", stroke:color, opacity:.35});
  const tx = alignEnd ? x-11 : x+11, anchor = alignEnd ? "end" : "start";
  const t = el("text", {x:tx, y:y+3, "class":"blip-label", "text-anchor":anchor});
  t.textContent = label;
  const s = el("text", {x:tx, y:y+15, "class":"blip-sub", "text-anchor":anchor});
  s.textContent = sub;
};

